{"results": [{"id": "hp_doc_a8231571e10648b085758aad2d96522b67ec5a48c447215024abb91b62d7358f", "title": "Gainsborough station group", "text": "The Gainsborough station group is a small station group of two railway stations in Gainsborough, England consisting of Central and Lea Road. The station group is printed on national rail tickets as GAINSBOROUGH STNS.", "score": 27.5607}, {"id": "hp_doc_9f7054c6c14ffffb74c3a7ec03ad8e0f626cd81f93b1f89359fe1409ab87be54", "title": "Gainsborough Central railway station", "text": "Gainsborough Central railway station is a railway station in the town of Gainsborough, Lincolnshire, England. The town's other station is the busier Gainsborough Lea Road. Until as recently as 2006, the station was shown to be one of the least busy in the country as trains only call there one day a week.", "score": 21.2476}, {"id": "hp_doc_95bab76b2493ff4821ec1e9b6e42c82695c5b64bc41488858337fc9f4247e26d", "title": "Gainsborough Lea Road railway station", "text": "Gainsborough Lea Road railway station is one of two stations that serve the town of Gainsborough in Lincolnshire, England, the other station being Gainsborough Central, which is located in the town centre. The station is managed by East Midlands Trains and is located 14.25 mi northwest of Lincoln Central on the A156 Lea Road in the south of the town. The station opened in 1867 on a single line of the Great Northern Railway, who ran four trains a day from Gainsborough to Lincoln.", "score": 20.5034}], "remaining_searches": 2}
